"cables.sydney_melbourne_adelaide_and_perth":"Sydney, Melbourne, Adelaide and Perth by sea, so your packets never have to cross the Nullarbor. Another one from the bloke who starts a fibre company every time he finishes a flat white.",
"cables.sydney_to_auckland_with_plenty_to":"Sydney to Auckland with plenty to spare.",
"cables.sydney_to_honolulu_and_not_a":"Sydney to Honolulu, and not a metre further. Getting to the mainland is your problem.",
"cables.sydney_to_noumea_wishes_it_were":"Sydney to Nouméa. Wishes it were a supercontinent.",
"cables.sydney_to_papua_new_guinea_and":"Sydney to Papua New Guinea and the Solomon Islands. Hums while it works.",
"cables.sydney_to_tokyo_by_way_of":"Sydney to Tokyo by way of Guam, going round and round since 2001.",
"cables.tahiti_to_hawaii_trolling_for":"Tahiti to Hawaii, trolling for bandwidth.",
"cables.tenerife_to_the_spanish_mainland_as":"Tenerife to the Spanish mainland. As long as it keeps singing, everything is fine.",
"cables.the_cable_that_brought_east_africa":"The cable that brought East Africa online, from Durban up to Djibouti and on to Mumbai. Still tells the story at every party.",
"cables.the_emirates_oman_and_pakistan_on":"The Emirates, Oman and Pakistan on one light little cable.",
"cables.the_first_cable_from_south_america":"The first cable from South America to Oceania. 14,000 km of very lonely glass.",
"cables.the_first_subsea_fiber_in_the":"The first subsea fiber in the American Arctic: Nome to Utqiaġvik, then over the North Slope to Anchorage. Sea ice keeps repair ships away half the year.",
"cables.the_newest_cable_from_south_africa":"The newest cable from South Africa to Madagascar, Réunion and Mauritius, shared by the islands’ own telcos.",
"cables.the_old_workhorse_s_younger_sibling":"The old workhorse’s younger sibling: Los Angeles to Sydney with a branch to Fiji.",
"cables.the_pretty_way_around_east_asia":"The pretty way around East Asia.",
"cables.the_previous_generation_still":"The previous generation. Still carries most of Pakistan, Sri Lanka and Bangladesh, held together with hope.",
"cables.the_sea_stallion_blackpool_to":"The Sea Stallion: Blackpool to Denmark, galloping round the north of Scotland.",
"cables.the_sequel_singapore_to_hong_kong":"The sequel: Singapore to Hong Kong, Taiwan, Japan and Korea, lit in 2025.",
"cables.the_seychelles_first_cable_to_tanzania":"The Seychelles’ first cable, to Tanzania, after years on satellite.",
"cables.the_straightest_line_across_the":"The straightest line across the Atlantic. Traders pay double to save a few milliseconds.",
"cables.tokyo_to_los_angeles_built_by":"Tokyo to Los Angeles, built by a search engine and five telcos holding hands.",
"cables.up_the_west_coast_of_africa":"Up the west coast of Africa. Something on it is always down.",
"cables.west_africa_s_first_big_cable":"West Africa’s first big cable, from Portugal to Cape Town. Old and wobbly, but still holding things up.",
