"events.a_cargo_ship_dragged_its_anchor":"A cargo ship dragged its anchor along the Baltic seabed for 100 km and swears it noticed nothing. Investigators are “looking into it”.",
"events.a_futuristic_city_that_is_not":"A futuristic city that is not built yet, demo day in {city}",
"events.a_gigaproject_wants_a_demo_bw":"<b>A gigaproject wants a demo.</b><br>{bw} for four days in {city}, to show off a city that is still mostly renderings. Check the Deals tab.",
"events.a_ship_drifting_without_power":"A ship drifting without power dragged its anchor through the Red Sea cables. Everyone blames everyone. Repair ships need permits from three governments.",
"events.a_state_owned_isp_accidentally":"A state-owned ISP “accidentally” announced your prefixes for 18 minutes. Their apology press release was suspiciously well written. Many networks are still routing your traffic into the void.",
"events.baltic_cable_damaged_a_cargo_ship":"<b>Baltic cable damaged</b><br>A cargo ship dragged its anchor for 100 km and swears it noticed nothing. You have no links on those cables.",
"events.baltic_cable_damaged_n_of_your":"<b>Baltic cable damaged</b><br>{n} of your links are down for about {d} days.",
"events.bgp_hijack_someone_else_is":"<b>BGP hijack</b><br>Someone else is announcing your prefixes. Reach is down until it is cleaned up.",
"events.cables_cut_in_the_red_sea":"<b>Cables cut in the Red Sea</b><br>A ship dragged its anchor across several cables. Everyone blames everyone. Luckily you do not use those cables.",
"events.cables_cut_in_the_red_sea_03e8":"<b>Cables cut in the Red Sea</b><br>{n} of your subsea links are down for about {d} days while the diplomats argue about repair ships.",
"events.call_everyone_you_know":"Call everyone you know",
"events.cogentle_and_goggle_are_in_a":"Cogentle and Goggle are in a peering spat. Goggle is unreachable through Cogentle transit.",
"events.drizzle_electric_sent_you_an_ipv6":"<b>Drizzle Electric sent you an IPv6 cake.</b><br>You sold it for $8k.",
"events.escalate_to_their_cto":"Escalate to their CTO",
"events.faceplant_got_tired_of_korean_usage":"Faceplant got tired of Korean usage fees and quietly moved Korean users to its Hong Kong servers. Pages crawl in for everyone in Seoul. The regulator is drafting a fine.",
"events.faceplant_rerouted_korea_via_hong":"<b>Faceplant rerouted Korea via Hong Kong.</b><br>Seoul users get a fifth less of it for 20 days, however you connect.",
"events.glitch_is_leaving_korea_the_game":"<b>Glitch is leaving Korea.</b><br>The game-streaming site says Korean network fees are “prohibitively expensive” and shuts down there. Its Seoul traffic drops by half, for good. Local streamers have already moved on.",
"events.golden_week_demand_in_mainland_china":"<b>Golden Week!</b><br>Demand in mainland China is up 40% for a week.",
"events.landing_permit_dispute_in_city_two":"<b>Landing permit dispute in {city}</b><br>Two ministries both claim the beach. No new subsea links can land there for 45 days.",
"events.name_hits_city_power_is_out":"<b>{name} hits {city}</b><br>Power is out and your POP is dark for two days. A generator would have saved it.",
"events.name_hits_city_the_grid_is":"<b>{name} hits {city}</b><br>The grid is down, but your backup generator kept the routers running.",
"events.name_knocked_out_power_in_city":"{name} knocked out power in {city}. Your POP has no generator.",
"events.new_season_of_stranger_pings_just":"<b>New season of “Stranger Pings” just dropped!</b><br>Eyeball demand is up 25% for a week. Got headroom?",
"events.optical_control_plane_meltdown_every":"<b>Optical control plane meltdown!</b><br>Every leased wave in {reg} just went dark at once. Your own dark fiber is fine. This is why people own fiber.",
"events.ordered_offline_in_city_a_government":"<b>Ordered offline in {city}</b><br>A government exam-day shutdown. Your POP there is dark for a day.",
"events.peering_spat_cogentle_de_peered":"<b>Peering spat!</b><br>Cogentle de-peered Goggle for 20 days. Goggle traffic over Cogentle transit is gone. Peer with Goggle directly or use another upstream.",
"events.regulators_ordered_every_network_in":"Regulators ordered every network in {city} to switch off for a day during national school exams. Yes, this really happens.",
"events.rural_broadband_grant_30k_the":"<b>Rural broadband grant: +$30k</b><br>The Ministry of Tubes likes what you are doing.",
"events.sanctions_the_republic_of":"<b>Sanctions!</b><br>The Republic of Paperworkistan sanctioned your router vendor’s favorite screw supplier. Spare parts are slow: router crashes take twice as long to fix for 60 days.",
"events.sovereign_internet_drill_moscow":"<b>Sovereign internet drill</b><br>Moscow unplugged itself from the rest of the internet for a day to see what happens. Everything leaving Russia is dark until tomorrow.",
"events.the_border_got_stricter_cross_border":"<b>The border got stricter.</b><br>Cross-border packet loss rises to 35% for 10 days. Premium routes are barely affected.",
"events.the_neighbours_have_fallen_out_a":"<b>The neighbours have fallen out.</b><br>A diplomatic spat closes borders and airspace around Qatar. Every link between Doha and Saudi Arabia or the UAE is down for about {n} days. Route the long way round, by sea.",
"events.trade_war_on_optics_two_governments":"<b>Trade war on optics</b><br>Two governments slapped tariffs on each other’s lasers. Optics cost 40% more for 90 days.",
"events.transit_prices_fell_8_they_do":"<b>Transit prices fell 8%.</b><br>They do this every year. Nobody knows where the bottom is.",
"events.typhoon_packet_loss":"Typhoon Packet-Loss",
"events.your_wave_supplier_pushed_one":"Your wave supplier pushed one malformed update to its optical control plane, and it flooded every node. All {n} leased waves you have in {reg} are dark. Their status page says “degraded”.",
