"failures.a_45_c_heatwave_in_city":"A 45 °C heatwave in {city}: the grid shed load, the chillers gave up and so did the generator at {dc}.",
"failures.a_b_is_down_same_cable":"{a}–{b} is down. Same cable, new anchor. The repair crew has started a loyalty card.",
"failures.a_backhoe_cut_the_metro_ring":"A backhoe cut the metro ring between your two sites in {city}. Turns out both fiber routes ran down the same street.",
"failures.a_backhoe_found_your_fiber_between":"A backhoe found your fiber between {a} and {b}.",
"failures.a_backhoe_putting_in_a_new":"A backhoe putting in a new servo dug straight through your {a}–{b} fiber. The plans said it was two metres to the left.",
"failures.a_beaver_chewed_through_your_a":"A beaver chewed through your {a}–{b} wave. It used the fiber to finish a dam.",
"failures.a_blackout_hit_city_and_your":"A blackout hit {city} and your POP has no generator. Every other network here has one. Buy one.",
"failures.a_botnet_of_40_000_smart":"a botnet of 40,000 smart toasters",
"failures.a_botnet_run_from_a_cloud":"a botnet run from a cloud you also host",
"failures.a_cargo_ship_forgot_to_raise":"A cargo ship “forgot” to raise its anchor and dragged it across your {a}–{b} cable. The owners are very sorry, and somewhat hard to reach.",
"failures.a_config_template_rendered_router_id":"A config template rendered “{{ router_id }}” literally in {city}. The router took it personally.",
"failures.a_cosmic_ray_flipped_a_bit":"A cosmic ray flipped a bit in your {city} router. It now believes 10.0.0.0/8 lives in Antarctica.",
"failures.a_crocodile_took_a_bite_out":"A crocodile took a bite out of your {a}–{b} fiber. It was not impressed.",
"failures.a_crypto_bro_shorting_your_stock":"a crypto bro shorting your stock",
"failures.a_curious_shark_bit_your_subsea":"A curious shark bit your subsea cable {a}–{b}.",
"failures.a_digger_found_your_a_b":"A digger found your {a}–{b} fiber. A different digger is coming to fix it.",
"failures.a_dirty_connector_on_a_b":"A dirty connector on {a}–{b} drops 2% of packets. TCP hates it: throughput collapses even though the link looks fine.",
"failures.a_drop_bear_fell_on_the":"A drop bear fell on the splicing crew on {a}–{b}. They refuse to work under trees, and the cut runs under trees.",
"failures.a_farmer_s_post_hole_digger":"A farmer’s post-hole digger found your {a}–{b} fiber. The sheep watched.",
"failures.a_ferry_dropped_anchor_in_cook":"A ferry dropped anchor in Cook Strait and found your {a}–{b} cable. The ferry is fine.",
"failures.a_firmware_bug_in_the_sys":"A firmware bug in the {sys} at {a} set every channel to “maintenance”.",
"failures.a_firmware_update_bricked_your":"A firmware update bricked your router in {city}.",
"failures.a_fishing_boat_with_an_unusually":"A fishing boat with an unusually heavy anchor cut {a}–{b}. It was not fishing.",
"failures.a_forestry_strike_stopped_the_waste":"A forestry strike stopped the waste-wood deliveries to the power plant that cools {dc}. No steam, no chillers: your routers in {city} run at half capacity.",
"failures.a_fridge_that_achieved_sentience_and":"a fridge that achieved sentience and chose violence",
"failures.a_gaming_clan_that_lost_one":"a gaming clan that lost one match",
"failures.a_great_white_took_an_interest":"A great white took an interest in your {a}–{b} cable and bit it. Then it spat it out: not enough flavour.",
"failures.a_huntsman_spider_the_size_of":"A huntsman spider the size of your hand moved into the router in {city}. Nobody would reach in to reboot it.",
"failures.a_kangaroo_boxed_your_field_tech":"A kangaroo boxed your field tech on {a}–{b}. The tech lost on points, and the splice can wait.",
"failures.a_kangaroo_hit_the_fiber_hut":"A kangaroo hit the fiber hut on {a}–{b}. The hut lost.",
"failures.a_kea_pulled_the_rubber_seals":"A kea pulled the rubber seals off the splice box on {a}–{b}, then started on the van. Kea are like that.",
"failures.a_kilometre_of_copper_went_missing":"A kilometre of “copper” went missing from your {a}–{b} trench. It was your fiber. The scrap yard sent it back with a note.",
"failures.a_landslide_in_the_andes_buried":"A landslide in the Andes buried your {a}–{b} fiber.",
"failures.a_llama_herd_trampled_the_fiber":"A llama herd trampled the fiber marker on {a}–{b}. Then a backhoe found the fiber.",
"failures.a_new_tech_in_a_tidied":"A new tech in {a} “tidied up” the cable mess. Your {a}–{b} link was part of the mess.",
"failures.a_new_tech_in_city_used":"A new tech in {city} used Vegemite as thermal paste. It conducts flavour, not heat, and your router cooked.",
"failures.a_optic_on_a_b_overheated":"A {optic} on {a}–{b} overheated and is now a very expensive keychain.",
"failures.a_optic_on_a_b_started":"A {optic} on {a}–{b} started reporting a temperature of 900°C. It was wrong, but it shut down anyway.",
"failures.a_possum_got_into_the_substation":"A possum got into the substation behind {dc} in {city}. The possum is fine. Your POP is not.",
"failures.a_power_cut_took_out_site":"A power cut took out {site} in {city}. {other} kept going, so the POP runs at half capacity. Anything plugged in only at the dark site is offline.",
"failures.a_pppoe_hop_shaved_8_bytes":"A PPPoE hop shaved 8 bytes off your MTU and nothing told the servers. Large transfers to {net} stall forever; small ones work fine, which makes it so much worse.",
"failures.a_printer_just_one_printer_nobody":"a printer. Just one printer. Nobody knows how",
