"homegrown_eyeballs.finland_s_biggest_mobile_network_unlimited":"Finland’s biggest mobile network, unlimited data played like a piano.",
"homegrown_eyeballs.finnish_broadband_and_mobile_it_s":"Finnish broadband and mobile. It’s in their DNA; test results pending.",
"homegrown_eyeballs.french_polynesia_s_mobile_network_came":"French Polynesia’s mobile network: it came, it saw, it connected the atolls.",
"homegrown_eyeballs.fur_elisa_across_the_gulf_of":"Für Elisa across the Gulf of Finland: the same tune, in Estonian.",
"homegrown_eyeballs.ghana_s_number_two_a_new":"Ghana’s number two: a new name, the same cables, very good salesmen.",
"homegrown_eyeballs.hong_kong_s_incumbent_broadband_full":"Hong Kong’s incumbent broadband, full of vigour and milk tea.",
"homegrown_eyeballs.iceland_s_incumbent_when_simon_says":"Iceland’s incumbent. When Símon says go, every packet takes the cable to Europe.",
"homegrown_eyeballs.iceland_s_mobile_challenger_burning_bright":"Iceland’s mobile challenger, burning bright on geothermal power.",
"homegrown_eyeballs.japan_s_biggest_mobile_network_bows":"Japan’s biggest mobile network, which bows deeply to its big sibling Not That Telecom.",
"homegrown_eyeballs.latvia_s_mobile_leader_let_me":"Latvia’s mobile leader: let me talk, then let me sell you 5G.",
"homegrown_eyeballs.malaysia_s_biggest_mobile_network_seldom":"Malaysia’s biggest mobile network: seldom dug up, seldom down.",
"homegrown_eyeballs.mozambique_s_rural_mobile_network_towers":"Mozambique’s rural mobile network, with towers in villages nobody else wired.",
"homegrown_eyeballs.namibia_s_mobile_network_lots_of":"Namibia’s mobile network: lots of desert, not much sea.",
"homegrown_eyeballs.namibia_s_state_incumbent_wired_across":"Namibia’s state incumbent, wired across the Namib one dune at a time.",
"homegrown_eyeballs.new_caledonia_s_cable_operator_can":"New Caledonia’s cable operator: can, will, eventually.",
"homegrown_eyeballs.new_zealand_s_number_two_renamed":"New Zealand’s number two, renamed and rebranded. It won, apparently.",
"homegrown_eyeballs.norwegian_fibre_from_the_power_company":"Norwegian fibre from the power company in Stavanger: you never know what you’re gonna get.",
"homegrown_eyeballs.ooh_redoo_s_maldives_branch_four":"Ooh-redoo’s Maldives branch: four bars on every sandbank.",
"homegrown_eyeballs.ooh_redoo_s_tunisian_network_mint":"Ooh-redoo’s Tunisian network: mint tea first, then megabits.",
"homegrown_eyeballs.pakistan_s_biggest_mobile_network_improvising":"Pakistan’s biggest mobile network, improvising its way through every outage.",
"homegrown_eyeballs.palau_s_mobile_challenger_your_pal":"Palau’s mobile challenger, your pal on every rock island.",
"homegrown_eyeballs.proxyminus_s_dancing_brand_in_luxembourg":"Proxyminus’s dancing brand in Luxembourg: it takes two to tango.",
"homegrown_eyeballs.senegal_s_number_two_freshly_renamed":"Senegal’s number two, freshly renamed and very sure of itself.",
"homegrown_eyeballs.serbia_s_incumbent_at_your_service":"Serbia’s incumbent, at your service.",
"homegrown_eyeballs.singapore_s_number_two_with_a":"Singapore’s number two, with a telescope trained on SingTell.",
"homegrown_eyeballs.sri_lanka_s_biggest_mobile_network_talks":"Sri Lanka’s biggest mobile network: talks to everyone, mostly to itself.",
"homegrown_eyeballs.sri_lanka_s_incumbent_adds_a":"Sri Lanka’s incumbent: adds a pinch of latency to every route.",
"homegrown_eyeballs.sweden_s_challenger_that_took_on":"Sweden’s challenger that took on Tell-Ya. One telco too many, says Tell-Ya.",
"homegrown_eyeballs.switzerland_s_incumbent_the_holes_in":"Switzerland’s incumbent. The holes in the coverage are a design feature.",
"homegrown_eyeballs.taiwan_s_number_three_never_hears":"Taiwan’s number three, which never hears a peering request the first time.",
"homegrown_eyeballs.takes_from_the_big_carriers_and":"Takes from the big carriers and gives cheap data bundles to Dhaka.",
"homegrown_eyeballs.tell_ya_s_estonian_daughter_e":"Tell-Ya’s Estonian daughter, which e-signs every peering request.",
"homegrown_eyeballs.thailand_s_biggest_mobile_network_cool":"Thailand’s biggest mobile network, cool in the Bangkok heat.",
"homegrown_eyeballs.the_challenger_that_made_french_broadband":"The challenger that made French broadband cheap: free as in beer, not as in peering.",
"homegrown_eyeballs.the_dominican_republic_s_other_big":"The Dominican Republic’s other big network. When in doubt, reboot.",
"homegrown_eyeballs.the_dutch_incumbent_peers_for_peanuts":"The Dutch incumbent: peers for peanuts, fibre to every polder.",
"homegrown_eyeballs.the_kingdom_s_challenger_always_mobilising":"The Kingdom’s challenger, always mobilising for the next megaproject.",
"homegrown_eyeballs.the_mobile_network_formerly_known_as":"The mobile network formerly known as something else, and not yet done renaming.",
"homegrown_eyeballs.the_philippines_other_mobile_giant_roaming":"The Philippines’ other mobile giant, roaming the archipelago.",
"homegrown_eyeballs.the_solomon_islands_mobile_challenger_to":"The Solomon Islands’ mobile challenger: to be or not to be online.",
