"networks.ships_parcels_and_packets_both":"Ships parcels and packets, both overnight.",
"networks.shopping_festivals_that_melt_traffic":"Shopping festivals that melt traffic graphs.",
"networks.short_videos_very_long_traffic":"Short videos, very long traffic graphs.",
"networks.sings_your_packets_across_asia":"Sings your packets across Asia-Pacific.",
"networks.small_fast_and_always_leaping_to":"Small, fast and always leaping to the next deal. Ribbit.",
"networks.social_media_everyone_keeps_falling":"Social media. Everyone keeps falling for it.",
"networks.social_network_with_perfect_vision":"Social network with perfect vision.",
"networks.speedy_by_name_owns_a_slice":"Speedy by name. Owns a slice of the cable to Singapore and keeps buying smaller ISPs.",
"networks.started_in_kansas_city_in_2012":"Started in Kansas City in 2012 and has been “coming to your city soon” ever since. Peers with anyone, almost everywhere.",
"networks.stockpiled_bandwidth_in_2020_and":"Stockpiled bandwidth in 2020 and still has a few rolls left.",
"networks.streams_40_of_evening_traffic_hands":"Streams 40% of evening traffic. Hands out free caches if you send enough eyeballs.",
"networks.taiwan_s_incumbent_stays_calm_while":"Taiwan’s incumbent. Stays calm while ships drag their anchors over its cables.",
"networks.tangerine_s_belgian_daughter_mobile":"Tangerine’s Belgian daughter: mobile, cable and a lot of Walloon highway dark fiber. Zesty.",
