"networks.telstraya_s_budget_brand_cheaper":"Telstraya’s budget brand. Cheaper, cheerier, and it still won’t peer with you.",
"networks.thailand_s_mobile_giant_its_coverage":"Thailand’s mobile giant. Its coverage maps are mostly true.",
"networks.the_big_regional_carrier_sees":"The big regional carrier. Sees everything clearly, especially your invoice.",
"networks.the_biggest_network_in_china_its":"The biggest network in China. Its CN-Too premium route skips the congested border, for a price.",
"networks.the_cheapest_plan_in_the_country":"The cheapest plan in the country. Smells like a bargain.",
"networks.the_cloud_it_s_just_someone":"The cloud. It's just someone else's Ashburn.",
"networks.the_kingdom_s_incumbent_once_you":"The Kingdom’s incumbent. Once you are in, you stay in.",
"networks.the_largest_mobile_network_on_earth":"The largest mobile network on Earth. Paid peering only.",
"networks.the_national_carrier_every_punchline":"The national carrier. Every punchline is pre-approved.",
"networks.the_original_cdn_maybe_it_is":"The original CDN. Maybe it is already in your rack.",
"networks.the_other_half_of_the_duopoly":"The other half of the duopoly, on copper and fiber. Strictly domestic: the world reaches it through its wholesale arm.",
