"rival_exchanges.a_community_exchange_in_a_hudson":"A community exchange in a Hudson Street basement. Schmear not included.",
"rival_exchanges.a_community_exchange_run_from_above":"A community exchange run from above a cider bar. Tiny, cheap, and every member gets a glass.",
"rival_exchanges.a_smaller_commercial_exchange_down":"A smaller commercial exchange down the road from DE-KICKS. Publishes its prices on one web page, which DE-KICKS considers an act of war. Ports come without a sales webinar.",
"rival_exchanges.dense_filling_and_very_cheap":"Dense, filling and very cheap.",
"rival_exchanges.every_session_comes_with_a_coffee":"Every session comes with a coffee break. Strictly enforced.",
"rival_exchanges.grilled_ports_served_with_mustard":"Grilled ports, served with mustard and a cold beer.",
"rival_exchanges.layered_resilient_and_somehow_always":"Layered, resilient and somehow always open.",
"rival_exchanges.lots_of_small_sessions_on_little":"Lots of small sessions on little plates.",
"rival_exchanges.member_owned_and_not_for_profit":"Member-owned and not-for-profit. Smaller than LYNX, but the AGM has biscuits.",
"rival_exchanges.mumbai_s_street_food_exchange_fast":"Mumbai’s street-food exchange. Fast, spicy and cheap.",
"rival_exchanges.one_fabric_across_the_whole_country":"One fabric across the whole country. Distributed, cheap and a little smug about it.",
"rival_exchanges.open_faced_cheap_and_available_at":"Open-faced, cheap and available at 3 a.m.",
"rival_exchanges.opens_at_six_comes_with_free":"Opens at six, comes with free snacks, closes when the last session drops.",
"rival_exchanges.run_by_hackers_on_caffeine_the":"Run by hackers on caffeine. The route server has a disco ball.",
"rival_exchanges.settlement_free_peering_with_frysian":"Settlement-free peering with Frysian roots. The 10G and 100G ports cost nothing. Bring an ASN and an appetite for route servers. Mayonnaise is extra.",
"rival_exchanges.started_in_somebody_s_garage_like":"Started in somebody’s garage, like everything else round here.",
"rival_exchanges.strong_sweet_and_cheaper_than_the":"Strong, sweet and cheaper than the incumbent.",
"rival_exchanges.takes_forever_to_set_up_but":"Takes forever to set up, but very filling.",
"rival_exchanges.the_challenger_fresh_every_morning_a":"The challenger. Fresh every morning, a bit crusty by the evening.",
"rival_exchanges.the_challenger_to_ix_straya_pops":"The challenger to IX Straya. Pops up at the edge of every city, including the ones nobody else bothers with. An acquired taste, like Vegemite.",
"rival_exchanges.the_challenger_to_the_de_kicks":"The challenger to the DE-KICKS fabric, wrapped and ready to go.",
"rival_exchanges.the_long_established_madrid_exchange":"The long-established Madrid exchange. Neutral interconnection, local flavour and a route server that never takes a siesta.",
"rival_exchanges.the_older_johannesburg_exchange_run":"The older Johannesburg exchange, run by the local ISP association. Knock on wood before every maintenance window.",
"rival_exchanges.tokyo_has_more_exchanges_than_anyone":"Tokyo has more exchanges than anyone can name. This one was started by a broadband giant and comes neatly packed, every member in its own compartment.",
"rival_exchanges.warsaw_has_more_exchanges_than":"Warsaw has more exchanges than anyone can count. This is the second biggest, this week.",
"rival_exchanges.you_can_t_see_the_fabric":"You can’t see the fabric, but it is definitely there.",
