"scenarios.1_6t_on_every_hop_from":"1.6T on every hop from Miami to Madrid and from Lisbon to Lagos, and 100 Gbps served",
"scenarios.90_days_in_a_row_with":"90 days in a row with 99.5% of demand served",
"scenarios.99_reach_and_150_gbps_served":"99% reach and 150 Gbps served",
"scenarios.a_path_from_cape_town_to_cairo_lagos":"A path from Cape Town to Cairo, Lagos and Nairobi on your network too, and 150 Gbps served",
"scenarios.a_path_from_los_angeles_to":"A path from Los Angeles to Sydney with 1.6T on every hop, a path from Los Angeles to Tokyo, and 150 Gbps served",
"scenarios.a_path_from_marseille_to_singapore":"A path from Marseille to Singapore, and 80 Gbps between Asia and the rest of your network for 30 days in a row",
"scenarios.amsterdam_hosting_capital_of_europe":"Amsterdam, hosting capital of Europe, in peak botnet season. Every smart toaster, baby monitor and unpatched fridge on Earth has picked a side, and it is not yours. A flood every few days, more and more of them in the terabits, while everything else keeps breaking too. You start with bigger gear unlocked, and you will need it.",
"scenarios.broadband_in_sydney_melbourne_served":"Broadband in Sydney, Melbourne, Brisbane, Adelaide and Perth, two different cables overseas, and 500 Gbps served",
"scenarios.cape_to_cairo":"Cape to Cairo",
"scenarios.cape_town_build_a_network_across":"Cape Town. Build a network across Africa: every border wants its own permit, and half the power grids are not on your side.",
"scenarios.cogentle_and_goggle_are_not_speaking":"Cogentle and Goggle are not speaking, and this time it is permanent. Buy the cheap transit if you dare.",
"scenarios.connect_panama_city_to_bogota_lima":"Bogotá, Lima, Santiago and São Paulo joined up to Panama City, and 150 Gbps served",
"scenarios.deliver_carnaval_in_full":"Deliver Carnaval in full",
"scenarios.every_cable_through_the_red_sea":"Every cable through the Red Sea is cut, and so is the hop to Egypt. Get Marseille talking to Singapore anyway: round Africa, overland, or the other way round the planet.",
"scenarios.every_ix_is_run_by_de":"Every IX is run by DE-KICKS",
"scenarios.eyeballs_grow_50_faster":"Eyeballs grow 50% faster",
"scenarios.fibre_to_the_basement":"Fibre to the Basement",
"scenarios.gangnam_style_peering":"Gangnam Style Peering",
"scenarios.hold_20_floods_5_of_them":"Hold 20 floods, 5 of them over 1 Tbps, keeping the city under attack at 97% or better",
"scenarios.honolulu_in_the_middle_of_the":"Honolulu, in the middle of the Pacific. The cables between the Americas, Asia and Australia are so long that a wave on them carries only 400G or 800G. Stop the light on an island, start it fresh, and every hop gets shorter and faster. You start with 1.6T gear unlocked.",
"scenarios.mid_atlantic_accent":"Mid-Atlantic Accent",
"scenarios.only_spatzle_ix":"Only Spätzle-IX",
"scenarios.order_and_progress":"Order and Progress",
"scenarios.ponta_delgada_azores_lisbon_lagos":"Ponta Delgada, in the Azores, halfway across the Atlantic. Florida to Spain is just too long for a 1.6T wave: straight across, it carries 1.2T. Land on the islands in between, start the light fresh, and every hop runs at 1.6T or better. Lisbon to Lagos does 1.6T in one go, at a price: the Canaries are cheaper. You start with 1.6T gear unlocked.",
"scenarios.ports_on_15_ix_brrr_exchanges_backbone":"Ports on 15 IX.brrr exchanges your backbone joins to São Paulo, one of them in Manaus, and 200 Gbps served",
"scenarios.reach_50_of_the_internet_and":"Reach 50% of the internet and serve 300 Gbps",
"scenarios.red_sea_crisis":"Red Sea Crisis",
"scenarios.rio_from_scratch_carnaval_starts_in":"Rio from scratch. Carnaval starts in 90 days and wants 400 Gbps for five days straight. The whole world is watching.",
"scenarios.sandbox_mode_a_billion_dollars_chaos":"<b>Sandbox mode</b><br>A billion dollars and every unlock. Chaos: {chaos}. Build the internet you always wanted, and keep a spare backhoe handy.",
"scenarios.sandbox_mode_a_billion_dollars_every":"<b>Sandbox mode</b><br>A billion dollars, every unlock, and nothing ever breaks. Build the internet you always wanted.",
"scenarios.sao_paulo_brazil_is_a_continent":"São Paulo. Brazil is a continent: forty IX.brrr exchanges, thousands of provedores, and the Amazon between you and the north.",
"scenarios.seoul_sender_pays_d":"Seoul, where the sender pays. Every Gbps a carrier delivers into Korea costs you a sender-pays fee on top of the transit bill, the three incumbents only talk over a paid PNI, home gigabit sells for the price of a bibimbap, and Korean users notice every millisecond. Tokyo transit is cheap, if your customers can stand the trip.",
"scenarios.seoul_sender_pays_goal":"{g} Gbps served, Seoul served well ({q}%), 99% reach and a monthly profit",
"scenarios.shark_season_subsea_cuts_twice_as":"Shark season: subsea cuts twice as likely",
"scenarios.start_in_panama_city_nothing_crosses":"Start in Panama City. Nothing crosses the Darién Gap by land, and the Andes are in the way of everything else.",
"scenarios.start_in_stuttgart_where_nobody":"Start in Stuttgart, where nobody sells transit. Reach the internet through peering, PNIs, caches and your own fiber only. No transit anywhere, ever.",
"scenarios.start_with_only_100k":"Start with only $100k",
"scenarios.sydney_2013_the_toilet_paper_group":"Sydney, 2013. The Toilet Paper Group ran its own fibre into apartment basements, and the national network cried cherry-picking. Your turn: skip the Nearly Broadband Network, pay the levy, and get there first.",
"scenarios.tallinn_nobody_sells_transit_anchors":"Tallinn, where nobody sells transit: your internet is across the water. Ships drag their anchors over Baltic cables three times as often as usual.",
"scenarios.the_cogentle_spat":"The Cogentle Spat",
"scenarios.transit_costs_30_more":"Transit costs 30% more",
"scenarios.twice_the_failures":"Twice the failures",
"scenarios.weekly_key":"Weekly {key}",
"scenarios.welcome_name_the_ripe_ncc_assigned":"<b>Welcome, {name}!</b><br>The RIPE NCC assigned you AS{asn}. Your first router is humming in {city}.",
"scenarios.you_have_n_days":"You have {n} days.",
